-- =========================================================
-- Project : Sridevi Enterprises
-- File    : 013_create_invoices.sql
-- Purpose : Invoices - one row per GST invoice generated by the Employee
--           Portal's Invoice Generator module (routes/receipts.py,
--           services/invoice_service.py). Replaces the standalone,
--           independently-deployed Receipt Generator project, which is
--           being folded into this application - see AI_CONTEXT.md
--           "Invoice Generator Module (Merge)".
--
--           Buyer/Consignee/state/total columns are a snapshot of what was
--           actually charged at the time the invoice was generated - they
--           are never recomputed from Catalog or from each other later.
--           InvoiceItems (014_create_invoiceitems.sql) carries the
--           matching per-line snapshot.
-- =========================================================

CREATE TABLE `Invoices` (
    `InvoiceID` INT AUTO_INCREMENT PRIMARY KEY,
    `InvoiceDate` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    `BuyerName` VARCHAR(255) NOT NULL,
    `BuyerAddress` TEXT NOT NULL,
    `BuyerContact` VARCHAR(20),
    `BuyerGSTIN` VARCHAR(15),
    `BuyerContract` VARCHAR(100),

    `ConsigneeName` VARCHAR(255) NOT NULL,
    `ConsigneeAddress` TEXT NOT NULL,
    `ConsigneeContact` VARCHAR(20),
    `ConsigneeGSTIN` VARCHAR(15),
    `ConsigneeContract` VARCHAR(100),

    -- Two-digit GST state codes (e.g. "37"), not full state names - see
    -- services/gst_service.py:STATE_NAMES for the code -> name lookup used
    -- only for display ("Place of Supply: Tamil Nadu (33)").
    `SellerState` VARCHAR(2) NOT NULL,
    `BuyerState` VARCHAR(2) NOT NULL,

    `TaxableTotal` DECIMAL(12, 2) NOT NULL,
    `CGSTTotal` DECIMAL(12, 2) NOT NULL DEFAULT 0,
    `SGSTTotal` DECIMAL(12, 2) NOT NULL DEFAULT 0,
    `IGSTTotal` DECIMAL(12, 2) NOT NULL DEFAULT 0,
    `RoundOff` DECIMAL(6, 2) NOT NULL DEFAULT 0,
    `GrandTotal` DECIMAL(12, 2) NOT NULL,
    `AmountInWords` VARCHAR(500) NOT NULL,

    -- Employees.EmployeeID (the same id StockHistory.EmployeeID uses,
    -- resolved via services/auth_service.py:get_employee_id_for_user()) -
    -- NOT NULL: an invoice is always generated by a logged-in employee.
    `CreatedBy` INT NOT NULL,
    `CreatedAt` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT `fk_invoices_createdby` FOREIGN KEY (`CreatedBy`) REFERENCES `Employees` (`EmployeeID`),

    INDEX `idx_invoices_invoicedate` (`InvoiceDate`),
    INDEX `idx_invoices_createdby` (`CreatedBy`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- IMPORTANT - invoice numbering, production go-live:
--
-- The standalone Receipt Generator project this module replaces was used
-- for testing only - it never issued or stored a real Sridevi Enterprises
-- customer invoice. There is no historical production invoice sequence to
-- migrate or continue from. InvoiceID's AUTO_INCREMENT simply starts fresh;
-- on a newly migrated production database this table is empty.
--
-- Before issuing the first real invoice, verify that:
--
--   SELECT COUNT(*) FROM Invoices;
--
-- returns 0, and that AUTO_INCREMENT is at a sane value (normally 1 for a
-- freshly created table - check with SHOW TABLE STATUS LIKE 'Invoices';).
--
-- Do NOT use 5090, or any other number seen on a development/reference
-- invoice, as the production starting number - it is a test value, not a
-- sequence to continue from.
